let name = String::from("Ada");
let moved = name;              // name no longer usable
let cloned = moved.clone();    // explicit heap copy
let length = borrowed_len(&moved);

fn borrowed_len(value: &str) -> usize { value.len() }

fn longest<'a>(left: &'a str, right: &'a str) -> &'a str {
    if left.len() >= right.len() { left } else { right }
}

fn first(values: &[String]) -> Option<&str> {
    values.first().map(String::as_str)
}

enum Payment { Card { last4: String }, Bank { iban: String }, Cash }

fn label(payment: &Payment) -> &str {
    match payment {
        Payment::Card { .. } => "card",
        Payment::Bank { .. } => "bank",
        Payment::Cash => "cash",
    }
}

